effect.shader:
float bayer2(vec2 p){
    return p.x<0.5 ? (p.y<0.5?0.0:3.0) : (p.y<0.5?2.0:1.0);
}
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 c = src.a>0.0? src.rgb/src.a : src.rgb;
    vec2 px = floor(acScreenNorm*acScreenSize);
    vec2 coarse = mod(floor(px/2.0), 2.0);
    vec2 fine = mod(px, 2.0);
    float th = (4.0*bayer2(coarse) + bayer2(fine))/16.0;
    float lv = max(levels,2.0);
    vec3 q = floor(c*(lv-1.0) + th)/(lv-1.0);
    gl_FragColor = vec4(clamp(q,0.0,1.0),1.0)*src.a;
}
